pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpTimestamp, uint256 rollNumber) public {
        amount = bound(amount, 10 ether, 10 ether);
        vm.deal(address(this), amount);
        vm.warp(warpTimestamp % type(uint64).max);
        vm.roll(rollNumber);
        (bool success, ) = address(c).call{value: amount}("");
        if (!success) return;
        assertTrue(c.pastBlockTime() - 1 <= block.timestamp);
    }
}
